async () => {
  const mod = await import('/packages/barocss-browser/dist/cdn/barocss.js');
  const rt = mod.getRuntime();
  const current = rt.options.config || {};
  const newConfig = {
    ...current,
    theme: {
      ...(current.theme || {}),
      extend: {
        ...((current.theme && current.theme.extend) || {}),
        colors: {
          ...((current.theme && current.theme.extend && current.theme.extend.colors) || {}),
          brand: '#5B21B6'
        }
      }
    }
  };
  rt.updateConfig(newConfig);
  // now register bg-brand usage
  const css = rt.getCss('bg-brand');
  return JSON.stringify({css});
}

